"use client"

import { type KeyboardEvent, useRef, useState } from "react"
import Image from "next/image"
import Link from "next/link"
import { Text } from "@astryxdesign/core/Text"

import type { AlbumPost, FlipMechanic } from "./types"

interface RecordStackProps {
  albums: AlbumPost[]
  index: number
  mechanic: FlipMechanic
}

export function RecordStack({ albums, index, mechanic }: RecordStackProps) {
  const [activeIndex, setActiveIndex] = useState(0)
  const [previewIndex, setPreviewIndex] = useState<number | null>(null)
  const items = useRef<(HTMLLIElement | null)[]>([])
  const preview = previewIndex === null ? null : albums[previewIndex]

  const moveTo = (nextIndex: number) => {
    const next = Math.max(0, Math.min(albums.length - 1, nextIndex))
    setActiveIndex(next)
    setPreviewIndex(next)
    items.current[next]?.scrollIntoView({ block: "center" })
  }

  const onKeyDown = (event: KeyboardEvent<HTMLOListElement>) => {
    const moves: Partial<Record<string, number>> = {
      ArrowDown: activeIndex + 1,
      ArrowUp: activeIndex - 1,
      End: albums.length - 1,
      Home: 0,
    }

    if (event.key in moves) {
      event.preventDefault()
      moveTo(moves[event.key] ?? activeIndex)
    }

    const activeAlbum = albums[activeIndex]
    if (event.key === "Enter" && activeAlbum) {
      window.location.assign(activeAlbum.href)
    }
  }

  return (
    <section className={`record-stack stack-${index + 1}`}>
      <ol
        className={`record-scroll mechanic-${mechanic}`}
        tabIndex={0}
        aria-keyshortcuts="ArrowUp ArrowDown Home End Enter"
        aria-label="Browse albums vertically. Use arrow keys, then Enter to open."
        onBlur={() => setPreviewIndex(null)}
        onFocus={() => setPreviewIndex(activeIndex)}
        onKeyDown={onKeyDown}
        onPointerLeave={() => setPreviewIndex(null)}
      >
        {albums.map((album, albumIndex) => (
          <li
            className="record-card"
            data-active={albumIndex === activeIndex || undefined}
            key={album.id}
            ref={(item) => {
              items.current[albumIndex] = item
            }}
          >
            <Link
              className="record-cover"
              href={album.href}
              tabIndex={-1}
              onPointerEnter={() => {
                setActiveIndex(albumIndex)
                setPreviewIndex(albumIndex)
              }}
            >
              <figure className="record-figure">
                <Image
                  className="record-art"
                  src={album.imageUrl}
                  alt={album.imageAlt}
                  fill
                  loading={albumIndex < 12 ? "eager" : "lazy"}
                  sizes="(min-width: 64rem) 12vw, 12rem"
                  unoptimized
                />
              </figure>
            </Link>
          </li>
        ))}
      </ol>

      {preview && (
        <aside className="record-preview" aria-live="polite">
          <Text type="label" color="inherit" maxLines={2}>
            {preview.title}
          </Text>
          <Text type="supporting" color="inherit" maxLines={1}>
            {preview.artist}
          </Text>
        </aside>
      )}
    </section>
  )
}

