 24	    setActiveIndex(next)
 25	    setPreviewIndex(next)
 26	    items.current[next]?.scrollIntoView({ block: "center" })
 27	  }
 28	
 29	  const onKeyDown = (event: KeyboardEvent<HTMLOListElement>) => {
 30	    const moves: Partial<Record<string, number>> = {
 31	      ArrowDown: activeIndex + 1,
 32	      ArrowUp: activeIndex - 1,
 33	      End: albums.length - 1,
 34	      Home: 0,
 35	    }
 36	
 37	    if (event.key in moves) {
 38	      event.preventDefault()
 39	      moveTo(moves[event.key] ?? activeIndex)
 40	    }
 41	
 42	    const activeAlbum = albums[activeIndex]
 43	    if (event.key === "Enter" && activeAlbum) {
 44	      window.location.assign(activeAlbum.href)
 45	    }
 46	  }
 47	
 48	  return (
 49	    <section className={`record-stack stack-${index + 1}`}>
 50	      <ol
 51	        className={`record-scroll mechanic-${mechanic}`}
 52	        tabIndex={0}
 53	        aria-keyshortcuts="ArrowUp ArrowDown Home End Enter"
 54	        aria-label="Browse albums vertically. Use arrow keys, then Enter to open."
 55	        onBlur={() => setPreviewIndex(null)}
 56	        onFocus={() => setPreviewIndex(activeIndex)}
 57	        onKeyDown={onKeyDown}
 58	        onPointerLeave={() => setPreviewIndex(null)}
 59	      >
 60	        {albums.map((album, albumIndex) => (
 61	          <li
 62	            className="record-card"
 63	            data-active={albumIndex === activeIndex || undefined}
 64	            key={album.id}
 65	            ref={(item) => {
 66	              items.current[albumIndex] = item
 67	            }}
 68	          >
 69	            <Link
 70	              className="record-cover"
 71	              href={album.href}
 72	              tabIndex={-1}
 73	              onPointerEnter={() => {
 74	                setActiveIndex(albumIndex)
 75	                setPreviewIndex(albumIndex)
 76	              }}
 77	            >
 78	              <figure className="record-figure">
 79	                <Image
 80	                  className="record-art"
 81	                  src={album.imageUrl}
 82	                  alt={album.imageAlt}
 83	                  fill
 84	                  loading={albumIndex < 12 ? "eager" : "lazy"}
 85	                  sizes="(min-width: 64rem) 12vw, 12rem"
 86	                  unoptimized
 87	                />
 88	              </figure>
 89	            </Link>
 90	          </li>
 91	        ))}
 92	      </ol>
 93	
 94	      {preview && (
 95	        <aside className="record-preview" aria-live="polite">
 96	          <Text type="label" color="inherit" maxLines={2}>
 97	            {preview.title}
 98	          </Text>
 99	          <Text type="supporting" color="inherit" maxLines={1}>
100	            {preview.artist}
101	          </Text>
102	        </aside>
103	      )}
104	    </section>
105	  )
106	}
